AGENT_STATUS_FILE = "agent_status.json"
AGENT_EVENTS_FILE = "agent_events.jsonl"
STATUS_PATH = LOGS_DIR / AGENT_STATUS_FILE
EVENTS_PATH = LOGS_DIR / AGENT_EVENTS_FILE
EXPERIMENT_EVENTS_PATH = LOGS_DIR / EXPERIMENT_EVENTS_FILE
EXPERIMENT_STATUS_PATH = LOGS_DIR / STATUS_FILE
REFRESH_SECONDS = 30
RECENT_EVENTS = 25
MAX_VALIDATION_PROBLEMS = 8

STATUS_ORDER = ("queued", "running", "blocked", "review", "done", "failed")
STATUS_GLYPH = {"queued": "○", "running": "◐", "blocked": "■", "review": "◆", "done": "●", "failed": "✕", "waiting_operator": "◆"}
