EXPERIMENT_STATUS_GLYPH = {"queued": "○", "running": "◐", "waiting_operator": "◆", "done": "●", "failed": "✕", "unknown": "?"}
FIRST_ATTEMPT_GLYPH = "✓"
NO_RUNS_TEXT = "No experiment runs yet"

