def _e(value: object) -> str:
    return html.escape("" if value is None else str(value))


def _fmt_duration(seconds: float) -> str:
    secs = max(int(seconds), 0)
    hours, rem = divmod(secs, 3600)
    mins, s = divmod(rem, 60)
    if hours:
        return f"{hours}h {mins:02d}m"
    return f"{mins}m {s:02d}s" if mins else f"{s}s"


def _fmt_elapsed(start: str | None, end: str | None) -> str:
    if not start:
        return "—"
    end_dt = parse_ts(end) if end else datetime.now(timezone.utc)
    return _fmt_duration((end_dt - parse_ts(start)).total_seconds())


def _waited_label(since: str | None, now: datetime) -> str:
    """'waiting for 7m 30s' from an ISO timestamp; falls back to quoting the raw value when it cannot be parsed."""
    if not since:
        return "waiting (since unknown)"
    try:
        return f"waiting for {_fmt_duration((now - parse_ts(str(since))).total_seconds())}"
    except (ValueError, TypeError):
        return f"waiting since {since}"


def _bar(pct: float, label: str = "") -> str:
    pct = max(0.0, min(100.0, float(pct or 0.0)))
    return (
        f'<div class="bar" role="progressbar" aria-valuenow="{pct:.0f}" aria-valuemin="0" aria-valuemax="100" '
        f'title="{_e(label)}"><div class="fill" style="width:{pct:.1f}%"></div></div>'
    )


def _status_cell(status: str) -> str:
    return f'<span class="st st-{_e(status)}">{STATUS_GLYPH.get(status, "?")} {_e(status)}</span>'


def _experiment_status_cell(status: str) -> str:
    return f'<span class="st st-{_e(status)}">{EXPERIMENT_STATUS_GLYPH.get(status, "?")} {_e(status)}</span>'


def _condition_label(condition: str) -> str:
    """Condition name spelled exactly as in the logs, with the fixed chart colour as a small swatch (text stays ink)."""
    return f'<span class="swatch" style="background:{condition_color(condition)}"></span>{_e(condition)}'


def _ordered_conditions(names) -> list[str]:
    names = set(names)
    return [c for c in CONDITION_ORDER if c in names] + sorted(c for c in names if c not in CONDITION_ORDER)


def _href(target: Path, out_dir: Path) -> str:
    """Relative link from the dashboard directory to a figure (``../figures/<name>.png`` for the defaults)."""
    try:
        return Path(os.path.relpath(Path(target).resolve(), Path(out_dir).resolve())).as_posix()
    except ValueError:  # different drives on Windows: a file URI still opens without a server
        return Path(target).resolve().as_uri()


def _guard(builder: Callable[..., str], *args) -> str:
    try:
        return builder(*args)
    except Exception as exc:  # noqa: BLE001 - one broken section must not blank the whole dashboard
        return f'<div class="card warn">This section could not be rendered: {_e(type(exc).__name__)}: {_e(exc)}</div>'


def _pick(snapshot_value, fallback):
    return fallback if snapshot_value is None else snapshot_value


# --------------------------------------------------------------------------- build sections (v1)


def _overall_section(status: dict) -> str:
    o = status.get("overall") or {}
    total = o.get("total_work_units", 0) or 0
    completed = o.get("completed_work_units", 0) or 0
    blocked = o.get("blocked_work_units", 0) or 0
    pct = o.get("percent_complete", 0) or 0
    gates = status.get("acceptance_gates_passed", False)
    eta_note = "Rough ETA = remaining weighted units x median observed seconds per completed unit; not a commitment."
    if o.get("eta_uncertain_due_to_blocked"):
        eta_note += " Blocked work makes this estimate more uncertain."
    return f"""
<div class="card hero">
  <div>
    <div class="sub">Overall completion (weighted work units)</div>
    <div class="big">{pct:g}%</div>
    <div style="margin-top:8px;width:320px">{_bar(pct, f"{completed:g} of {total:g} units")}</div>
    <div class="sub" style="margin-top:6px">{completed:g} of {total:g} units complete
      &middot; {blocked:g} units blocked
      &middot; acceptance gates: <strong>{"passed" if gates else "not yet passed"}</strong>
      {"" if gates else "(100% is reserved until they pass)"}</div>
  </div>
  <div>
    <div class="sub">ETA</div>
    <div style="font-size:18px;font-weight:650;margin-top:6px">{_e(o.get("eta_label", "ETA unavailable"))}</div>
    <div class="sub" style="margin-top:6px">computed {_e(o.get("eta_computed_at", "—"))}
      &middot; median {_e(o.get("median_seconds_per_unit") if o.get("median_seconds_per_unit") is not None else "—")} s/unit
      over {_e(o.get("completed_unit_count", 0))} completed units</div>
    <div class="sub muted" style="margin-top:4px;max-width:420px">{eta_note}</div>
  </div>
</div>"""


def _counts_section(status: dict) -> str:
    counts = (status.get("overall") or {}).get("counts") or {}
    tiles = [("configured", counts.get("configured", len(status.get("agents", []))))]
    tiles += [(s, counts.get(s, 0)) for s in STATUS_ORDER]
    cells = "".join(
        f'<div class="tile"><div class="k">{STATUS_GLYPH.get(k, "")} {_e(k)}</div><div class="v">{_e(v)}</div></div>'
        for k, v in tiles
    )
    return f'<div class="grid tiles">{cells}</div>'


def _agents_section(status: dict) -> str:
    agents = status.get("agents", [])
    if not agents:
        return '<div class="card muted">No agents registered yet.</div>'
    rows = []
    for a in agents:
        blockers = ", ".join(a.get("blocked_by") or []) or "—"
        units = f"{a.get('completed_work_units', 0):g}/{a.get('total_work_units', 0):g}"
        rows.append(
            "<tr>"
            f"<td class='mono'>{_e(a.get('agent_id'))}</td>"
            f"<td>{_e(a.get('role'))}</td>"
            f"<td>{_status_cell(a.get('status', 'queued'))}</td>"
            f"<td>{_e(a.get('current_task') or '—')}</td>"
            f"<td class='mono'>{_e(a.get('last_artifact') or '—')}</td>"
            f"<td class='num'>{_e(_fmt_elapsed(a.get('started_at'), a.get('finished_at')))}</td>"
            f"<td>{_bar(a.get('percent_complete', 0), units)}<div class='sub' style='margin-top:3px'>{units} units &middot; {a.get('percent_complete', 0):g}%</div></td>"
            f"<td>{_e(a.get('eta_label'))}</td>"
            f"<td>{_e(blockers)}</td>"
            f"<td class='sub'>{_e(a.get('note') or '')}</td>"
            "</tr>"
        )
    return f"""
<div class="card wrap"><table>
<thead><tr><th>Agent</th><th>Role</th><th>Status</th><th>Current work</th><th>Latest artifact</th>
<th class="num">Elapsed</th><th>Progress</th><th>ETA</th><th>Blocked by</th><th>Note</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table></div>"""


def _blocked_section(status: dict) -> str:
    blocked = [a for a in status.get("agents", []) if a.get("status") == "blocked"]
    if not blocked:
        return '<div class="card muted">No blocked work.</div>'
    items = "".join(
        f"<li><span class='mono'>{_e(a['agent_id'])}</span> blocked by "
        f"<span class='mono'>{_e(', '.join(a.get('blocked_by') or []) or 'unspecified')}</span>"
        f" &mdash; {_e(a.get('note') or a.get('current_task') or '')}"
        f" ({max(a.get('total_work_units', 0) - a.get('completed_work_units', 0), 0):g} units remaining)</li>"
        for a in blocked
    )
    return f'<div class="card"><ul style="margin:0;padding-left:18px">{items}</ul></div>'


def _events_section(logs_dir: Path) -> str:
    try:
        events = read_jsonl(logs_dir / AGENT_EVENTS_FILE)
    except ValueError as exc:
        return f'<div class="card warn">{AGENT_EVENTS_FILE} could not be parsed: {_e(exc)}</div>'
    if not events:
        return '<div class="card muted">No events yet.</div>'
    rows = []
    for ev in reversed(events[-RECENT_EVENTS:]):
        detail = ev.get("artifact") or ev.get("note") or ev.get("task") or ""
        rows.append(
            "<tr>"
            f"<td class='mono'>{_e(ev.get('timestamp'))}</td><td class='mono'>{_e(ev.get('agent_id'))}</td>"
            f"<td>{_e(ev.get('event'))}</td><td>{_status_cell(ev.get('status', '')) if ev.get('status') else ''}</td>"
            f"<td>{_e(ev.get('current_task') or '')}</td><td class='sub'>{_e(detail)}</td>"
            "</tr>"
        )
    return f"""
<div class="card wrap"><table>
<thead><tr><th>Time (UTC)</th><th>Agent</th><th>Event</th><th>Status</th><th>Task</th><th>Detail</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table></div>"""


# --------------------------------------------------------------------------- experiment area (v2)


def experiment_runs(logs_dir: Path | str = LOGS_DIR) -> dict:
    """Merge the runner's status snapshot with the folded logs: ``{"status", "summary", "runs": [{run_id, snapshot, logged, conditions}]}``."""
    logs_dir = Path(logs_dir)
    status = read_status(logs_dir)
    summary = summarize_runs(logs_dir)
    runs = []
    for run_id in sorted(set(status.get("runs") or {}) | set(summary["run_ids"])):
        snapshot = (status.get("runs") or {}).get(run_id) or {}
        logged = summary["runs"].get(run_id) or {"conditions": {}, "provider_modes": [], "model_identifiers": [], "operators": []}
        conditions = _ordered_conditions(set(snapshot.get("conditions") or {}) | set(logged["conditions"]))
        runs.append({"run_id": run_id, "snapshot": snapshot, "logged": logged, "conditions": conditions})
    return {"status": status, "summary": summary, "runs": runs}


def _finals(log_cond: dict) -> list[dict]:
    return [t["final"] for t in (log_cond.get("tasks") or {}).values() if t.get("final")]


def _condition_row(condition: str, snap: dict, logged: dict, tasks_total_default: int | None, now: datetime) -> str:
    finals = _finals(logged)
    status_word = str(snap.get("status") or "unknown")
    current_bits = [snap.get("current_task"), snap.get("current_node"), f"attempt {snap['attempt']}" if snap.get("attempt") else None]
    current = " · ".join(str(b) for b in current_bits if b) or "—"
    pending = snap.get("pending_request")
    if pending:
        since = snap.get("waiting_since")
        pending_html = (
            f'<div class="mono pending">{_e(pending)}</div>'
            f'<div class="sub">{_e(_waited_label(since, now))} &middot; since {_e(since or "unknown")}</div>'
        )
    else:
        pending_html = '<span class="muted">—</span>'
    done = int(_pick(snap.get("tasks_completed"), logged.get("tasks_done", 0)) or 0)
    total = snap.get("tasks_total") or tasks_total_default
    tasks_text = f"{done}/{total}" if total else f"{done}"
    tasks_html = (_bar(done / total * 100 if total else 0, tasks_text) + f"<div class='sub' style='margin-top:3px'>{tasks_text}</div>") if total else tasks_text
    steps_used = _pick(snap.get("operator_steps_used"), sum(int(f.get("operator_steps_used") or 0) for f in finals))
    cap = snap.get("operator_steps_cap")
    steps_text = f"{steps_used}/{cap}" if cap is not None else f"{steps_used}"
    retries = _pick(snap.get("retries"), logged.get("retries", 0))
    errors = _pick(snap.get("execution_errors"), logged.get("execution_errors", 0))
    created = _pick(snap.get("skills_created"), len(logged.get("skills_created") or []))
    retrieved = _pick(snap.get("skills_retrieved"), sum(len(f.get("skills_retrieved") or []) for f in finals))
    mean = logged.get("mean_score")
    return (
        "<tr>"
        f"<td>{_condition_label(condition)}</td>"
        f"<td>{_experiment_status_cell(status_word)}</td>"
        f"<td class='mono'>{_e(current)}</td>"
        f"<td>{pending_html}</td>"
        f"<td>{tasks_html}</td>"
        f"<td class='num'>{_e(steps_text)}</td>"
        f"<td class='num'>{_e(retries)}</td>"
        f"<td class='num'>{_e(errors)}</td>"
        f"<td class='num'>{_e(created)} / {_e(retrieved)}</td>"
        f"<td class='num'>{'—' if mean is None else f'{float(mean):.2f}'}</td>"
        f"<td>{_e(snap.get('eta_label') or '—')}</td>"
        "</tr>"
    )


def _score_grid(run: dict, task_ids: list[str]) -> str:
    snap_conditions = run["snapshot"].get("conditions") or {}
    log_conditions = run["logged"].get("conditions") or {}
    rows = []
    for condition in run["conditions"]:
        snap = snap_conditions.get(condition) or {}
        logged = log_conditions.get(condition) or {}
        cells, scores = [], []
        for task_id in task_ids:
            final = ((logged.get("tasks") or {}).get(task_id) or {}).get("final")
            score = final.get("evaluator_score_total") if final else (snap.get("scores") or {}).get(task_id)
            first = final.get("first_attempt_passed") if final else (snap.get("first_attempt_pass") or {}).get(task_id)
            if isinstance(score, (int, float)):
                scores.append(float(score))
                mark = f" {FIRST_ATTEMPT_GLYPH}" if first else ""
                title = "passed on first attempt" if first else "needed a retry, or did not pass"
                cells.append(f'<td title="{title}">{score:.2f}{mark}</td>')
            elif snap.get("current_task") == task_id and snap.get("status") in ("waiting_operator", "running"):
                word = "waiting" if snap["status"] == "waiting_operator" else "running"
                cells.append(f'<td class="warn" title="{_e(snap["status"])}">{EXPERIMENT_STATUS_GLYPH[snap["status"]]} {word}</td>')
            else:
                cells.append('<td class="muted">—</td>')
        mean = f"{sum(scores) / len(scores):.2f}" if scores else "—"
        rows.append(f"<tr><td class='cond'>{_condition_label(condition)}</td>{''.join(cells)}<td class='num'>{mean}</td></tr>")
    head = "".join(f"<th class='task'>{_e(t)}</th>" for t in task_ids)
    return f"""
<div class="card wrap"><table class="scores">
<thead><tr><th class="cond">Condition</th>{head}<th class="num">Mean</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table>
<div class="sub" style="margin-top:8px">Final rubric score per task (0&ndash;4, higher is better) &middot; {FIRST_ATTEMPT_GLYPH} = passed on the first attempt
&middot; &mdash; = no final record yet &middot; columns follow the configured task order.</div></div>"""


def _run_header(run: dict) -> str:
    snap, logged = run["snapshot"], run["logged"]
    bits = [f"mode <code>{_e(snap.get('mode'))}</code>" if snap.get("mode") else None]
    provider = snap.get("provider")
    provider_meta: dict = {}
    if isinstance(provider, dict):  # the runner stores {"provider_mode", "operator", "model_identifier"}
        provider_meta = provider
        provider = provider.get("provider_mode")
    provider = provider or ", ".join(logged.get("provider_modes") or [])
    bits.append(f"provider <code>{_e(provider)}</code>" if provider else None)
    models = ", ".join(logged.get("model_identifiers") or ([str(provider_meta["model_identifier"])] if provider_meta.get("model_identifier") else []))
    bits.append(f"model <code>{_e(models)}</code>" if models else None)
    operators = ", ".join(logged.get("operators") or ([str(provider_meta["operator"])] if provider_meta.get("operator") else []))
    bits.append(f"operator <code>{_e(operators)}</code>" if operators else None)
    freeze = snap.get("freeze_sha256")
    bits.append(f"freeze <code>{_e(str(freeze)[:12])}</code>" if freeze else None)
    bits.append(f"created {_e(snap['created_at'])}" if snap.get("created_at") else None)
    if not snap:
        bits.append("<span class='warn'>no status snapshot for this run; rows are derived from the logs only</span>")
    return f"<h3>run <span class='mono'>{_e(run['run_id'])}</span></h3><div class='sub' style='margin:-4px 0 8px'>{' &middot; '.join(b for b in bits if b)}</div>"


def _experiment_section(logs_dir: Path) -> str:
    merged = experiment_runs(logs_dir)
    status, summary, runs = merged["status"], merged["summary"], merged["runs"]
    if not runs:
        return (
            f'<div class="card muted">{NO_RUNS_TEXT}. This area fills from <code>logs/{STATUS_FILE}</code> and '
            f"<code>logs/{EXPERIMENT_EVENTS_FILE}</code> once a run starts "
            "(<code>uv run python -m src.run_experiment init ...</code> or <code>run-stub</code>).</div>"
        )
    now = datetime.now(timezone.utc)
    configured = configured_task_order()
    parts = [
        f'<div class="sub">Snapshot <code>{_e(rel(logs_dir / STATUS_FILE))}</code> updated {_e(status.get("updated_at") or "never")} '
        f'&middot; logs <code>{_e(summary["source"])}</code>'
        + (f' &middot; <span class="warn">{summary["skipped_records"]} invalid record(s) skipped (see log validation below)</span>' if summary.get("skipped_records") else "")
        + "</div>"
    ]
    pending_total = 0
    for run in runs:
        snap_conditions = run["snapshot"].get("conditions") or {}
        log_conditions = run["logged"].get("conditions") or {}
        rows = []
        for condition in run["conditions"]:
            snap = snap_conditions.get(condition) or {}
            if snap.get("pending_request"):
                pending_total += 1
            rows.append(_condition_row(condition, snap, log_conditions.get(condition) or {}, len(configured) or None, now))
        parts.append(_run_header(run))
        parts.append(
            f"""<div class="card wrap"><table>
<thead><tr><th>Condition</th><th>Status</th><th>Current task &middot; node</th><th>Pending operator request</th><th>Tasks done</th>
<th class="num">Operator steps used / cap</th><th class="num">Retries</th><th class="num">Exec. errors</th>
<th class="num">Skills created / retrieved</th><th class="num">Mean score</th><th>Rough ETA</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table></div>"""
        )
        observed: set[str] = set()
        for cond in log_conditions.values():
            observed.update((cond.get("tasks") or {}).keys())
        for cond in snap_conditions.values():
            observed.update((cond.get("scores") or {}).keys())
            if cond.get("current_task"):
                observed.add(str(cond["current_task"]))
        task_ids = sorted(set(configured) | observed, key=task_sort_key)
        parts.append("<h3>Per-task scores</h3>")
        parts.append(_score_grid(run, task_ids))
    if pending_total:
        parts.insert(1, f'<div class="card" style="margin-top:8px"><span class="st st-waiting_operator">{EXPERIMENT_STATUS_GLYPH["waiting_operator"]} waiting_operator</span> &middot; {pending_total} condition(s) are waiting on an operator step; the request file paths are listed in the rows below.</div>')
    return "\n".join(parts)


def _figures_section(figures_dir: Path, out_dir: Path) -> str:
    manifest = read_json(figures_dir / MANIFEST_FILE, default=None) or {}
    by_name = {f.get("name"): f for f in manifest.get("figures") or [] if isinstance(f, dict)}
    cards, missing = [], []
    for name, (file_name, title, description) in FIGURE_CATALOGUE.items():
        path = figures_dir / file_name
        if not path.exists():
            missing.append(file_name)
            continue
        meta = by_name.get(name) or {}
        rendered = datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).isoformat(timespec="seconds")
        extra = ""
        if meta:
            runs = ", ".join(meta.get("run_ids") or []) or "none"
            extra += f'<span class="sub">Source: {_e(", ".join(meta.get("sources") or []))} &middot; runs: {_e(runs)}</span>'
            if meta.get("notes"):
                extra += f'<span class="sub warn">{_e(" | ".join(str(n) for n in meta["notes"]))}</span>'
            if meta.get("observations") is False:
                extra += '<span class="sub warn">no observations yet: the figure shows empty axes, nothing is invented</span>'
        cards.append(
            f'<figure><img src="{_e(_href(path, out_dir))}" alt="{_e(title)}"><figcaption>{_e(title)}'
            f'<span class="sub">{_e(description)}</span>{extra}'
            f'<span class="sub muted">rendered {_e(rendered)} &middot; {_e(rel(path))}</span></figcaption></figure>'
        )
    topology = figures_dir.parent / "graphs" / TOPOLOGY_FILE
    if topology.exists():
        rendered = datetime.fromtimestamp(topology.stat().st_mtime, timezone.utc).isoformat(timespec="seconds")
        cards.append(
            f'<figure><img src="{_e(_href(topology, out_dir))}" alt="Designed LangGraph workflow"><figcaption>Designed LangGraph workflow'
            '<span class="sub">The architecture as designed (src/claims_graph.designed_topology()), not observed behaviour.</span>'
            f'<span class="sub muted">rendered {_e(rendered)} &middot; {_e(rel(topology))}</span></figcaption></figure>'
        )
    if not cards:
        return (
            '<div class="card muted">No figures rendered yet. <code>uv run python -m src.charts</code> computes them from the logs into '
            f"<code>{_e(rel(figures_dir))}/</code>; the runner refreshes them after every finalised task.</div>"
        )
    out = ""
    if manifest.get("generated_at"):
        out += f'<div class="sub" style="margin-bottom:8px">Figures generated {_e(manifest["generated_at"])} from <code>{_e(manifest.get("logs_dir"))}</code> &middot; runs: {_e(", ".join(manifest.get("run_ids") or []) or "none")} &middot; manifest <code>{_e(rel(figures_dir / MANIFEST_FILE))}</code></div>'
    out += f'<div class="figs">{"".join(cards)}</div>'
    if missing:
        out += f'<div class="sub muted" style="margin-top:8px">not rendered yet: {_e(", ".join(missing))}</div>'
    return out


def _count_lines(path: Path) -> int:
    with open(path, "r", encoding="utf-8") as fh:
        return sum(1 for line in fh if line.strip())


def _log_sources_section(logs_dir: Path) -> str:
    rows = []
    for name in (*LOG_FILES, STATUS_FILE):
        path = logs_dir / name
        if path.exists():
            stat = path.stat()
            lines = _count_lines(path) if name.endswith(".jsonl") else "—"
            modified = datetime.fromtimestamp(stat.st_mtime, timezone.utc).isoformat(timespec="seconds")
            rows.append(f"<tr><td class='mono'>{_e(rel(path))}</td><td class='num'>{_e(lines)}</td><td class='num'>{stat.st_size:,}</td><td class='mono'>{_e(modified)}</td></tr>")
        else:
            rows.append(f"<tr><td class='mono'>{_e(rel(path))}</td><td class='num muted'>—</td><td class='num muted'>—</td><td class='muted'>not written yet</td></tr>")
    problems = validate_logs(logs_dir)
    if problems:
        shown = "".join(f"<li>{_e(p)}</li>" for p in problems[:MAX_VALIDATION_PROBLEMS])
        more = f"<li>… {len(problems) - MAX_VALIDATION_PROBLEMS} more</li>" if len(problems) > MAX_VALIDATION_PROBLEMS else ""
        validation = f'<div class="warn" style="margin-top:10px">Log validation: {len(problems)} problem(s)</div><ul class="problems">{shown}{more}</ul>'
    else:
        validation = '<div class="sub" style="margin-top:10px">Log validation: no problems (every line parses and carries its required fields; no secret-looking keys).</div>'
    return f"""
<div class="card wrap"><table>
<thead><tr><th>Log file</th><th class="num">Records</th><th class="num">Bytes</th><th>Last modified (UTC)</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table>{validation}</div>"""


# --------------------------------------------------------------------------- render


def build_html(status: dict, logs_dir: Path | str = LOGS_DIR, figures_dir: Path | str = FIGURES_DIR, out_dir: Path | str | None = None) -> str:
    logs_dir = Path(logs_dir)
    figures_dir = Path(figures_dir)
    out_dir = Path(out_dir) if out_dir else DASHBOARD_PATH.parent
    generated = utc_now()
    sources = [logs_dir / AGENT_STATUS_FILE, logs_dir / AGENT_EVENTS_FILE, logs_dir / STATUS_FILE, *(logs_dir / n for n in LOG_FILES), figures_dir / MANIFEST_FILE]
    return f"""<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<meta http-equiv="refresh" content="{REFRESH_SECONDS}">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>claims-skill-loop &middot; progress</title>
<style>{CSS}</style></head>
<body><main>
<h1>claims-skill-loop &mdash; build &amp; experiment progress</h1>
<div class="sub">Generated {_e(generated)} &middot; auto-refreshes every {REFRESH_SECONDS} s &middot; tracker updated {_e(status.get("updated_at") or "never")}</div>

<h2>Overall completion</h2>
{_overall_section(status)}

<h2>Agent workload</h2>
{_counts_section(status)}
<div style="height:12px"></div>
{_agents_section(status)}

<h2>Blocked work</h2>
{_blocked_section(status)}

<h2>Experiment</h2>
{_guard(_experiment_section, logs_dir)}

<h2>Figures</h2>
{_guard(_figures_section, figures_dir, out_dir)}

<h2>Experiment logs</h2>
{_guard(_log_sources_section, logs_dir)}

<h2>Recent agent events</h2>
{_events_section(logs_dir)}

<footer>Sources: {", ".join(f"<code>{_e(rel(p))}</code>" for p in sources)}.
Results from <code>stub</code> runs are deterministic simulations, not LLM results; <code>manual</code> runs record the operator's
decisions (every record carries <code>provider_mode</code>, <code>operator</code> and <code>model_identifier</code>).
Educational demonstration on synthetic healthcare claims data; nothing here is medical, actuarial, or operational evidence.</footer>
</main></body></html>
"""


def render(out_path: Path | str | None = None, logs_dir: Path | str | None = None, figures_dir: Path | str | None = None) -> Path:
    """Write the dashboard (defaults: ``artifacts/dashboard/progress.html`` from ``logs/`` and ``artifacts/figures/``)."""
    logs_dir = Path(logs_dir) if logs_dir else LOGS_DIR
    figures_dir = Path(figures_dir) if figures_dir else FIGURES_DIR
    target = Path(out_path) if out_path else DASHBOARD_PATH
    status = read_json(logs_dir / AGENT_STATUS_FILE, default=None) or {"agents": [], "overall": {}, "updated_at": None}
    return atomic_write_text(target, build_html(status, logs_dir=logs_dir, figures_dir=figures_dir, out_dir=target.parent))


def main(argv: list[str] | None = None) -> int:
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")  # type: ignore[attr-defined]
    except Exception:  # noqa: BLE001
        pass
    p = argparse.ArgumentParser(prog="dashboard", description="Render the static progress dashboard from the tracker status, experiment status and JSONL logs.")
    p.add_argument("--out", default=None, help=f"output HTML path (default {rel(DASHBOARD_PATH)})")
    p.add_argument("--logs-dir", default=None, help=f"logs directory (default {rel(LOGS_DIR)})")
    p.add_argument("--figures-dir", default=None, help=f"figures directory (default {rel(FIGURES_DIR)})")
    args = p.parse_args(argv)
    path = render(args.out, args.logs_dir, args.figures_dir)
    print(f"dashboard written: {rel(path)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
